using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Security.Cryptography;using System.Web.Script.Serialization;
internal static class Guard351Regression {
 static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic;
 static Assembly asm;static List<string> checks=new List<string>();
 static object Call(object target,string method,params object[] args){return target.GetType().GetMethod(method,Flags).Invoke(target,args);}
 static void Check(bool value,string label){if(!value)throw new Exception(label);checks.Add(label);}
 static void Refuse(Action action,string label){bool refused=false;try{action();}catch(TargetInvocationException ex){refused=ex.InnerException is IOException||ex.InnerException is InvalidDataException||ex.InnerException is ArgumentException;}Check(refused,label);}
 static string Hash(string file){using(var sha=SHA256.Create())using(var s=(Stream)asm.GetType("PCGuard.SafeFiles").GetMethod("OpenStable",Flags).Invoke(null,new object[]{file,false}))return BitConverter.ToString(sha.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
 static int Main(string[] args){try{string root=Path.GetFullPath(args[0]);asm=Assembly.LoadFrom(Path.Combine(root,"PC Guard.exe"));string fixture=Path.Combine(root,"Data","Tests","import-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(fixture);
 var type=asm.GetType("PCGuard.HashListImport");var parse=type.GetMethod("Parse",Flags);string a=new string('a',64),b=new string('b',64);
 var rows=(Dictionary<string,object>[])parse.Invoke(null,new object[]{"# source\n"+a+"\n\""+b+"\",2026\n"+a.ToUpperInvariant(),"sample.csv"});Check(rows.Length==2,"TXT/CSV SHA256 deduplicated");Check(rows.All(r=>(string)r["action"]=="alert"),"Imported lists alert only");
 Refuse(()=>parse.Invoke(null,new object[]{new string('a',32),"md5.txt"}),"MD5 rejected");Refuse(()=>parse.Invoke(null,new object[]{"x"+a,"wrong.txt"}),"Embedded alphanumeric token rejected");Refuse(()=>parse.Invoke(null,new object[]{new string('a',65537),"long.txt"}),"Oversized line rejected");
 object store=Activator.CreateInstance(asm.GetType("PCGuard.Store"),Flags,null,new object[]{Path.Combine(fixture,"App")},null);object engine=Activator.CreateInstance(asm.GetType("PCGuard.Engine"),Flags,null,new object[]{store},null);var before=(Dictionary<string,object>)Call(engine,"Info");string benign=Path.Combine(fixture,"benign.dat");File.WriteAllText(benign,"Ordinary import regression fixture");string list=Path.Combine(fixture,"hashes.txt");File.WriteAllText(list,"sha256,date\n"+Hash(benign)+",2026-11-09\n"+Hash(benign));
 var result=(Dictionary<string,object>)Call(engine,"Import",list,Hash(list));Check(Convert.ToInt32(result["hashes"])==Convert.ToInt32(before["hashes"])+1,"Import merges and deduplicates existing database");Check(Convert.ToInt32(result["blockRules"])==Convert.ToInt32(before["blockRules"]),"Existing blocking rules retained");var verdict=(Dictionary<string,object>)Call(engine,"Scan",benign);Check((string)verdict["verdict"]=="published-ioc","Actual engine detects imported SHA as warning");
 string state=(string)result["sha256"];Refuse(()=>Call(engine,"Import",list,new string('0',64)),"Wrong expected SHA rejected");Check((string)((Dictionary<string,object>)Call(engine,"Info"))["sha256"]==state,"Rejected import preserves database");string empty=Path.Combine(fixture,"empty.txt");File.WriteAllText(empty,"md5,date\n0123456789abcdef0123456789abcdef,2026");Refuse(()=>Call(engine,"Import",empty,Hash(empty)),"Import without SHA256 rejected");Check((string)((Dictionary<string,object>)Call(engine,"Info"))["sha256"]==state,"Malformed list preserves database");
 string report=Path.Combine(root,"Data","Tests","guard351-import.json");File.WriteAllText(report,new JavaScriptSerializer().Serialize(new{checks=checks.Count,failures=0,results=checks,actualProductionEngine=true,malwareDownloaded=false}));Console.WriteLine("Import regression: "+checks.Count+" passed");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}